custom_css:
/*
 * 十二时辰·亥·迷幻
 * 十二时辰 · 第十二篇 · 亥时 21:00—23:00 · 核心词「迷幻」· 主题名「循环」
 * 作者：if love　｜　本主题可自用、可修改；转载或二次发布请保留作者署名。
 *
 * 字体：马善政楷书（标题）/ 霞鹜文楷屏幕版（正文）/ Cormorant Garamond 斜体（点缀数字）
 *       分别来自 Google Fonts 与 jsDelivr，均为 OFL 开源字体；加载失败时回落到系统楷体/宋体。
 * 背景：粒子莫比乌斯 ∞、偶极子场线、棱镜星爆为内嵌图片；光轨是内嵌 SVG 动画。
 *
 * 可调开关（改 :root 里的值即可）：
 *   --hai-user-bg     想露出自己在酒馆里设置的背景图 → 改成 1，同时把 --hai-floor-alpha 改成 0
 *   --hai-scene-top   ∞ 场景离顶部的距离
 */
@import url("https://fonts.googleapis.com/css2?family=Ma+Shan+Zheng&family=Cormorant+Garamond:ital,wght@1,500&display=swap");
@import url("https://cdn.jsdelivr.net/npm/lxgw-wenkai-screen-webfont@1.7.0/style.css");

@property --hai-ang {
  syntax: "<angle>";
  inherits: false;
  initial-value: 200deg;
}
@keyframes hai-spin { to { --hai-ang: 560deg; } }
@media (prefers-reduced-motion: reduce) { #chat .mes, #completion_prompt_manager_list li, .popup .popup-button-ok { animation: none !important; } }

:root {
  --hai-night: #0C0C10;
  --hai-deep: #14131E;
  --hai-pearl: #EDEBF4;
  --hai-ink: #24203A;
  --hai-ink-2: #4D4572;
  --hai-mist: #A9A6C2;
  --hai-peri: #8C90F2;
  --hai-peri-rgb: 140, 144, 242;
  --hai-q: #F2D2E6;
  --hai-em: #C7C3E6;
  --hai-line: rgba(237, 235, 244, .2);
  --hai-line-strong: rgba(237, 235, 244, .38);
  --hai-panel: rgba(20, 19, 30, .74);
  --hai-panel-solid: #14131E;
  --hai-field: rgba(8, 8, 12, .62);
  --hai-font-title: "Ma Shan Zheng", "STKaiti", "KaiTi", "Kaiti SC", serif;
  --hai-font-body: "LXGW WenKai Screen", "LXGW WenKai", "STKaiti", "KaiTi", "Noto Serif SC", "Songti SC", serif;
  --hai-font-num: "Cormorant Garamond", "Georgia", "Times New Roman", serif;
  --hai-user-bg: 0;
  --hai-floor-alpha: 1;
  --hai-scene-top: calc(var(--topBarBlockSize, 50px) + 1.5vh);
  --hai-scene-size: min(100vw, 1000px);
  --hai-c: rgba(140, 144, 242, .85);
  --hai-brk:
    linear-gradient(var(--hai-c), var(--hai-c)) 0 0 / 16px 1.5px no-repeat,
