    linear-gradient(var(--hai-c), var(--hai-c)) 0 100% / 16px 1.5px no-repeat,
    linear-gradient(var(--hai-c), var(--hai-c)) 0 100% / 1.5px 16px no-repeat,
    linear-gradient(var(--hai-c), var(--hai-c)) 100% 100% / 16px 1.5px no-repeat,
