#ai-config-button .drawer-icon,
#sys-settings-button .drawer-icon,
#advanced-formatting-button .drawer-icon,
#WI-SP-button .drawer-icon,
#user-settings-button .drawer-icon,
#backgrounds-button .drawer-icon,
#extensions-settings-button .drawer-icon,
#persona-management-button .drawer-icon,
#rightNavHolder .drawer-icon, #rightNavDrawerIcon,
#options_button,
#extensionsMenuButton,
#mes_continue,
#mes_impersonate,
#mes_stop {
  -webkit-mask: var(--hai-i) center / 22px 22px no-repeat !important;
  mask: var(--hai-i) center / 22px 22px no-repeat !important;
  background-color: currentColor !important;
  background-image: none !important;
  min-width: 26px;
  min-height: 26px;
}
#ai-config-button .drawer-icon::before,
#sys-settings-button .drawer-icon::before,
#advanced-formatting-button .drawer-icon::before,
#WI-SP-button .drawer-icon::before,
#user-settings-button .drawer-icon::before,
#backgrounds-button .drawer-icon::before,
#extensions-settings-button .drawer-icon::before,
#persona-management-button .drawer-icon::before,
#rightNavHolder .drawer-icon::before,
#rightNavDrawerIcon::before,
#options_button::before,
#extensionsMenuButton::before,
#mes_continue::before,
#mes_impersonate::before,
#mes_stop::before { content: "" !important; }
#leftSendForm > div, #rightSendForm > div { opacity: 1 !important; }

/* ───── 抽屉面板 ───── */
#top-settings-holder .drawer-content,
#right-nav-panel, #left-nav-panel,
#floatingPrompt, #cfgConfig, #movingDivs > div {
  background: var(--hai-brk), rgba(14, 13, 22, .94) !important;
  border: 1px solid var(--hai-line) !important;
  border-radius: 0 !important;
  box-shadow: 0 18px 50px rgba(0, 0, 0, .55) !important;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  color: var(--hai-pearl);
}
#top-settings-holder .drawer-content h3, #top-settings-holder .drawer-content h4,
.popup h3, .popup h4 {
  font-family: var(--hai-font-title);
  font-weight: 400;
  letter-spacing: .12em;
  color: var(--hai-pearl);
}

/* ───── 扩展面板 / 所有折叠标题栏（替换默认灰渐变） ───── */
.inline-drawer-toggle.inline-drawer-header,
#extensions_settings .inline-drawer-header,
#extensions_settings2 .inline-drawer-header {
  display: flex !important;
  align-items: center;
  justify-content: flex-start !important;
  gap: 10px;
  background: rgba(12, 12, 16, .72) !important;
  background-image: none !important;
  border: 1px solid var(--hai-line) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 10px 12px !important;
  color: var(--hai-pearl) !important;
  font-family: var(--hai-font-body);
  letter-spacing: .14em;
  filter: none !important;
  opacity: 1 !important;
}
.inline-drawer-toggle.inline-drawer-header::before {
  content: "";
  flex: none;
  width: 32px;
  height: 13px;
  background: var(--hai-head-inf) center / contain no-repeat;
  pointer-events: none;
}
.inline-drawer-toggle.inline-drawer-header > .inline-drawer-icon { margin-left: auto; color: var(--hai-mist) !important; }
.inline-drawer-toggle.inline-drawer-header:hover { border-color: rgba(var(--hai-peri-rgb), .55) !important; }
.inline-drawer-toggle.inline-drawer-header:has(.inline-drawer-icon.up) {
  background: var(--hai-brk), rgba(24, 22, 40, .95) !important;
  border-color: rgba(var(--hai-peri-rgb), .55) !important;
}
.inline-drawer-toggle.inline-drawer-header:has(.inline-drawer-icon.up)::before { background-image: var(--hai-head-inf-on); }
.inline-drawer-toggle.inline-drawer-header:has(.inline-drawer-icon.up) > .inline-drawer-icon { color: var(--hai-pearl) !important; }
.inline-drawer-content {
  background: rgba(12, 12, 16, .5) !important;
  border: 1px solid var(--hai-line);
  border-top: 0;
  border-radius: 0 !important;
  padding: 10px 12px !important;
}
#extensions_settings .extension_container, #extensions_settings2 .extension_container { margin-bottom: 10px; }

/* ───── 聊天楼层：居中轴 · 头像压在上框线 ───── */
#chat .mes {
  position: relative;
  content-visibility: visible !important;
  contain: none !important;
  width: auto !important;
  max-width: none !important;
  box-sizing: border-box !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  margin: 60px 10px 24px !important;
  padding: 0 18px 22px !important;
  overflow: visible;
}
/* 边框：扭带框 */
#chat .mes { border: 2px solid transparent !important; border-image: conic-gradient(from var(--hai-ang), rgba(255,255,255,.95), rgba(140,144,242,.6) 14%, rgba(237,235,244,.06) 33%, rgba(142,230,242,.55) 48%, rgba(255,255,255,.9) 56%, rgba(140,144,242,.18) 74%, rgba(255,154,203,.55) 87%, rgba(255,255,255,.95)) 1 !important; background: var(--hai-panel) !important; animation: hai-spin 9s linear infinite; }
#chat .mes > .mes_block::after {
  content: ""; position: absolute; left: calc(50% - 30px); bottom: -11px; width: 60px; height: 22px;
  background: var(--hai-hr-inf) center / 56px 20px no-repeat, var(--hai-night);
  pointer-events: none; z-index: 2;
}
/* 大楼层号（左上）*/
#chat .mes::before {
  content: attr(mesid);
  position: absolute;
  left: 16px;
  top: 10px;
  font-family: var(--hai-font-num);
  font-style: italic;
  font-weight: 500;
  font-size: 34px;
  line-height: 1;
  color: rgba(var(--hai-peri-rgb), .85);
  text-shadow: -1px 0 rgba(255, 154, 203, .45), 1px 0 rgba(142, 230, 242, .45);
  pointer-events: none;
}
#chat .mes[is_user="false"]::after {
  content: "";
  position: absolute;
  right: 6px;
  top: -17px;
  width: 34px;
  height: 34px;
  background: var(--hai-spark) center / contain no-repeat;
  pointer-events: none;
  z-index: 2;
}
#chat .mes .mesIDDisplay { display: none !important; }

/* 头像列 → 顶部居中：头像 + 数据签 */
#chat .mes > .mesAvatarWrapper {
  position: relative;
  display: flex !important;
  flex-direction: row !important;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  align-self: stretch;
  width: auto !important;
  margin: -42px 0 0 !important;
  padding: 0 !important;
}
#chat .mes > .mesAvatarWrapper::before {
  content: "圈";
  position: absolute;
  left: 9px;
  top: 88px;
  font-family: var(--hai-font-body);
  font-size: 11px;
  letter-spacing: .3em;
  color: var(--hai-mist);
  pointer-events: none;
}
#chat .mes .mesAvatarWrapper .avatar {
  flex: none;
  width: 62px !important;
  height: 80px !important;
  margin: 0 calc(50% - 31px) 8px !important;
  border-radius: 0 !important;
  border: 1px solid var(--hai-line-strong) !important;
  outline: 1px solid rgba(var(--hai-peri-rgb), .35);
  outline-offset: 3px;
  background: var(--hai-night);
  box-shadow: none !important;
  overflow: hidden;
}
#chat .mes .mesAvatarWrapper .avatar img {
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  object-fit: cover;
  border-radius: 0 !important;
}
#chat .mes[is_user="false"] > .mesAvatarWrapper::after {
  content: "";
  position: absolute;
  left: calc(50% - 54px);
  top: 46px;
  width: 108px;
  height: 46px;
  background: var(--hai-av-inf) center / contain no-repeat;
  pointer-events: none;
  z-index: 2;
}
/* 数据签：耗时 / token */
#chat .mes .mes_timer,
#chat .mes .tokenCounterDisplay {
  display: inline-flex !important;
  align-items: baseline;
  gap: 5px;
  margin: 0 3px;
  padding: 1px 9px 2px;
  border: 1px solid var(--hai-line);
  background: rgba(12, 12, 16, .55);
  font-family: var(--hai-font-num);
  font-style: italic;
  font-size: 13px;
  line-height: 1.4;
  letter-spacing: .04em;
  color: var(--hai-pearl) !important;
  opacity: 1 !important;
}
#chat .mes .mes_timer:empty, #chat .mes .tokenCounterDisplay:empty { display: none !important; }
#chat .mes .mes_timer::before,
#chat .mes .tokenCounterDisplay::before {
  font-family: var(--hai-font-body);
  font-style: normal;
  font-size: 11px;
  letter-spacing: .1em;
  color: var(--hai-peri);
}
#chat .mes .mes_timer::before { content: "迟"; }
#chat .mes .tokenCounterDisplay::before { content: "光"; }

/* 名字 / 时间：居中 */
#chat .mes .mes_block { width: 100%; min-width: 0; padding: 0 !important; }
#chat .mes .ch_name { justify-content: center !important; margin-top: 10px; }
#chat .mes .ch_name > .flex-container,
#chat .mes .ch_name > div:first-child {
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 2px;
  flex: 1 1 auto;
}
#chat .mes .ch_name .name_text {
  font-family: var(--hai-font-title);
  font-size: 1.75em;
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: .12em;
  color: var(--hai-pearl) !important;
  text-shadow: 0 0 12px rgba(var(--hai-peri-rgb), .55);
}
#chat .mes .timestamp {
  font-family: var(--hai-font-num);
  font-style: italic;
  font-size: 13px;
  letter-spacing: .08em;
  color: var(--hai-mist) !important;
  opacity: 1 !important;
}
#chat .mes .timestamp::before { content: "— "; }
#chat .mes .timestamp::after { content: " —"; }
#chat .mes .mes_buttons {
  position: absolute !important;
  top: 12px;
  right: 14px;
  z-index: 3;
}
#chat .mes .mes_text { padding: 0 4px !important; margin-top: 12px; text-align: justify; }
#chat .mes .mes_buttons .mes_button,
#chat .mes .extraMesButtonsHint,
#chat .mes .mes_edit_buttons .menu_button,
#chat .mes .swipe_left, #chat .mes .swipe_right {
  color: var(--hai-mist) !important;
  opacity: 1 !important;
  filter: none !important;
}
#chat .mes .mes_buttons .mes_button:hover,
#chat .mes .extraMesButtonsHint:hover,
#chat .mes .swipe_left:hover, #chat .mes .swipe_right:hover { color: var(--hai-pearl) !important; }
#chat .mes .swipes-counter { font-family: var(--hai-font-num); font-style: italic; color: var(--hai-mist) !important; opacity: 1 !important; }

/* ───── 用户楼层 = 纸带内侧（蛋白石月面） ───── */
#chat .mes[is_user="true"] {
  border-image: conic-gradient(from var(--hai-ang), rgba(36,32,58,.9), rgba(140,144,242,.8) 14%, rgba(36,32,58,.12) 33%, rgba(78,170,190,.7) 48%, rgba(36,32,58,.85) 56%, rgba(140,144,242,.3) 74%, rgba(190,80,140,.6) 87%, rgba(36,32,58,.9)) 1 !important;
  --hai-c: rgba(36, 32, 58, .6);
  background:

    var(--hai-sketch) -30px calc(100% + 34px) / 110px 110px no-repeat,
    linear-gradient(rgba(240, 236, 246, .55), rgba(240, 236, 246, .55)),
    radial-gradient(30% 40% at 18% 30%, #8FC3F0, transparent 70%),
    radial-gradient(28% 36% at 58% 18%, #F6B07A, transparent 70%),
    radial-gradient(30% 40% at 82% 62%, #F1A9C6, transparent 70%),
    radial-gradient(26% 34% at 40% 78%, #B8A6EC, transparent 70%),
    radial-gradient(20% 30% at 70% 30%, #9FD6B8, transparent 70%),
    #E7E1EE !important;
}
#chat .mes[is_user="true"]::before { color: rgba(77, 69, 114, .8); text-shadow: none; }
#chat .mes[is_user="true"] > .mesAvatarWrapper::before { color: var(--hai-ink-2); }
#chat .mes[is_user="true"] .mes_timer,
#chat .mes[is_user="true"] .tokenCounterDisplay { background: rgba(255, 255, 255, .45); border-color: rgba(36, 32, 58, .25); color: var(--hai-ink) !important; }
#chat .mes[is_user="true"] .mesAvatarWrapper .avatar { outline-color: rgba(36, 32, 58, .3); }
#chat .mes[is_user="true"] .mes_text,
#chat .mes[is_user="true"] .ch_name .name_text { color: var(--hai-ink) !important; text-shadow: none; }
#chat .mes[is_user="true"] .mesAvatarWrapper .avatar { border-color: var(--hai-ink) !important; }
#chat .mes[is_user="true"] .timestamp,
#chat .mes[is_user="true"] .mes_buttons .mes_button,
#chat .mes[is_user="true"] .extraMesButtonsHint,
#chat .mes[is_user="true"] .swipes-counter { color: var(--hai-ink-2) !important; }
#chat .mes[is_user="true"] .mes_text q { color: #7D2F5E !important; }
#chat .mes[is_user="true"] .mes_text em { color: var(--hai-ink-2) !important; text-decoration-color: rgba(77, 69, 114, .7); }
#chat .mes[is_user="true"] .mes_text strong { color: var(--hai-ink) !important; text-shadow: none; background: linear-gradient(transparent 62%, rgba(var(--hai-peri-rgb), .35) 62%); }

/* ───── 正文分层 ───── */
#chat .mes .mes_text {
  font-family: var(--hai-font-body);
  line-height: 1.95;
  letter-spacing: .08em;
  color: var(--hai-pearl);
}
#chat .mes .mes_text q { color: var(--hai-q) !important; }
#chat .mes .mes_text em, #chat .mes .mes_text i {
  font-style: normal;
  color: var(--hai-em) !important;
  text-decoration: underline dotted rgba(var(--hai-peri-rgb), .9);
  text-decoration-thickness: 2px;
  text-underline-offset: 5px;
}
#chat .mes .mes_text strong, #chat .mes .mes_text b {
  font-weight: 500;
  color: #fff !important;
  text-shadow: 0 0 8px rgba(var(--hai-peri-rgb), .8);
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}
#chat .mes .mes_text u { text-decoration: underline wavy rgba(var(--hai-peri-rgb), .8); text-underline-offset: 5px; }
#chat .mes .mes_text del { color: var(--hai-mist); text-decoration-color: rgba(255, 154, 203, .7); }
#chat .mes .mes_text a { color: var(--hai-peri) !important; text-underline-offset: 4px; }
#chat .mes .mes_text blockquote {
  margin: .8em 0;
  padding: .6em 1em;
  border: 1px dashed var(--hai-line-strong) !important;
  border-radius: 0;
  background: rgba(var(--hai-peri-rgb), .06);
  color: var(--hai-em);
}
#chat .mes .mes_text hr {
  height: 24px;
  border: 0 !important;
  margin: 1em 0;
  background:
    var(--hai-hr-inf) center / 64px 24px no-repeat,
    linear-gradient(90deg, transparent, var(--hai-line-strong) 40%, transparent 40%, transparent 60%, var(--hai-line-strong) 60%, transparent) center / 100% 1px no-repeat;
}
#chat .mes .mes_text code {
  font-family: ui-monospace, "Cascadia Code", Menlo, monospace;
  background: rgba(var(--hai-peri-rgb), .14) !important;
  color: #E6E4FF !important;
  border-radius: 0 !important;
  padding: 0 .3em;
}
#chat .mes .mes_text pre {
  background: #0A0A0F !important;
  border: 1px solid var(--hai-line) !important;
  border-radius: 0 !important;
}
#chat .mes .mes_text pre code, #chat .mes .mes_text pre code.hljs { background: transparent !important; padding: 0; }
#chat .mes[is_user="true"] .edit_textarea {
  background: rgba(255, 255, 255, .6) !important;
  color: var(--hai-ink) !important;
  border-color: rgba(36, 32, 58, .5) !important;
}
#chat .mes[is_user="true"] .mes_edit_buttons .menu_button { color: var(--hai-ink) !important; border-color: rgba(36, 32, 58, .35) !important; background: rgba(255, 255, 255, .4) !important; }
#chat .mes[is_user="true"] .mes_text code { background: rgba(36, 32, 58, .1) !important; color: var(--hai-ink) !important; }

/* 思考块 / 编辑框 */
#chat .mes .mes_reasoning_details {
  border: 1px dashed var(--hai-line-strong) !important;
  border-radius: 0 !important;
  background: rgba(var(--hai-peri-rgb), .05) !important;
}
#chat .mes .mes_reasoning_summary { color: var(--hai-mist) !important; font-family: var(--hai-font-body); letter-spacing: .1em; }
#chat .mes .mes_reasoning { color: var(--hai-em) !important; }
#chat .mes .edit_textarea, #chat .mes .reasoning_edit_textarea {
  background: var(--hai-field) !important;
  color: var(--hai-pearl) !important;
  border: 1px solid rgba(var(--hai-peri-rgb), .7) !important;
  border-radius: 0 !important;
  font-family: var(--hai-font-body);
  line-height: 1.9;
}

/* ───── 输入区 ───── */
#send_form {
  background: rgba(12, 12, 16, .84) !important;
  border: 1px solid var(--hai-line-strong) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
#send_textarea {
  font-family: var(--hai-font-body) !important;
  color: var(--hai-pearl) !important;
  letter-spacing: .06em;
  background: transparent !important;
}
#send_textarea::placeholder { color: var(--hai-mist); opacity: 1; }
#leftSendForm .fa-solid, #rightSendForm .fa-solid,
#options_button, #extensionsMenuButton {
  color: var(--hai-mist) !important;
  opacity: 1 !important;
  filter: none !important;
}
#leftSendForm .fa-solid:hover, #rightSendForm .fa-solid:hover,
#options_button:hover, #extensionsMenuButton:hover { color: var(--hai-pearl) !important; }
#send_but::before { content: "" !important; }
#send_but {
  color: transparent !important;
  background: var(--hai-spark) center / 28px 28px no-repeat !important;
  filter: none !important;
}
#send_but:hover { filter: none !important; transform: scale(1.08); }
#mes_stop { color: var(--hai-peri) !important; opacity: 1 !important; }

/* ───── 弹窗（含历史聊天） ───── */
.popup {
  background: var(--hai-brk), #12111B !important;
  border: 1px solid var(--hai-line-strong) !important;
  border-radius: 0 !important;
  box-shadow: 0 24px 70px rgba(0, 0, 0, .65) !important;
  color: var(--hai-pearl) !important;
  font-family: var(--hai-font-body);
}
.popup::backdrop { background: rgba(5, 4, 10, .72); backdrop-filter: blur(3px); }
.popup .popup-content { color: var(--hai-pearl); }
.select_chat_block {
  background: rgba(237, 235, 244, .035) !important;
  border: 1px solid var(--hai-line) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  color: var(--hai-pearl) !important;
  opacity: 1 !important;
}
.select_chat_block:hover { border-color: rgba(var(--hai-peri-rgb), .6) !important; background: rgba(var(--hai-peri-rgb), .08) !important; }
.select_chat_block[highlight="true"] {
  background: rgba(var(--hai-peri-rgb), .18) !important;
  border-color: rgba(var(--hai-peri-rgb), .8) !important;
}
.select_chat_block_filename { color: var(--hai-pearl) !important; letter-spacing: .06em; }
.select_chat_block_mes { color: var(--hai-em) !important; opacity: 1 !important; }
.select_chat_block .chat_file_size, .select_chat_block .chat_messages_num,
.select_chat_block_date, .select_chat_info {
  font-family: var(--hai-font-num);
  font-style: italic;
  color: var(--hai-mist) !important;
  opacity: 1 !important;
}

/* ───── 去官方发光 / 黑影 ───── */
:root { --shadowWidth: 0 !important; }
.menu_button, .menu_button_default, .mes_button, .extraMesButtonsHint, .fa-solid, .fa-regular,
.welcomePanel .menu_button, #welcomePanel .menu_button, .mes .mes_buttons > div {
  text-shadow: none !important;
}

/* ───── 按钮：直角细框 + 角点；确定键 = 珍珠底墨字 ───── */
.menu_button, .menu_button_icon, .menu_button_default {
  --hai-c: rgba(140, 144, 242, .9);
  background:
    linear-gradient(var(--hai-c), var(--hai-c)) 0 0 / 5px 1px no-repeat,
    linear-gradient(var(--hai-c), var(--hai-c)) 0 0 / 1px 5px no-repeat,
    linear-gradient(var(--hai-c), var(--hai-c)) 100% 100% / 5px 1px no-repeat,
    linear-gradient(var(--hai-c), var(--hai-c)) 100% 100% / 1px 5px no-repeat,
    rgba(237, 235, 244, .04) !important;
  border: 1px solid var(--hai-line) !important;
  border-radius: 0 !important;
  color: var(--hai-pearl) !important;
  box-shadow: none !important;
  filter: none !important;
  font-family: var(--hai-font-body);
  letter-spacing: .08em;
  transition: background-color .2s, border-color .2s, color .2s;
}
.menu_button:hover, .menu_button_icon:hover {
  background-color: rgba(var(--hai-peri-rgb), .2) !important;
  border-color: rgba(var(--hai-peri-rgb), .75) !important;
  color: #fff !important;
}
.menu_button.toggleEnabled, .menu_button.active, .menu_button.selected {
  background-color: rgba(var(--hai-peri-rgb), .3) !important;
  border-color: var(--hai-peri) !important;
  color: #fff !important;
}
.menu_button.disabled, .menu_button:disabled { opacity: .45 !important; }
.popup .popup-controls { gap: 12px !important; }
.popup .popup-controls .menu_button { min-width: 6.5em; padding: 8px 18px !important; }
/* 确定键：燕尾缎带（不是长方形；形状画在背景里，按钮本身不动） */
.popup .popup-controls .menu_button.popup-button-ok, .popup .popup-controls .menu_button_default {
  background: url("data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%20100%2040%22%20preserveAspectRatio=%22none%22%20width=%22100%22%20height=%2240%22%3E%3Cpath%20d=%22M.8%20.8H99.2L91%2020%2099.2%2039.2H.8L9%2020Z%22%20fill=%22rgba(26,24,44,.95)%22%20stroke=%22rgba(140,144,242,.85)%22%20stroke-width=%221.3%22%20vector-effect=%22non-scaling-stroke%22/%3E%3C/svg%3E") center / 100% 100% no-repeat !important;
  border: 0 !important;
  outline: 0;
  color: #fff !important;
  letter-spacing: .3em;
  text-indent: .3em;
  padding: 9px 30px !important;
  filter: none !important;
}
.popup .popup-button-ok::before, .popup .menu_button_default::before {
  content: ""; display: inline-block; width: 12px; height: 12px; margin-right: 6px; vertical-align: -1px;
  background: var(--hai-spark) center / contain no-repeat;
}
.popup .popup-controls .menu_button.popup-button-ok:hover { background-image: url("data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%20100%2040%22%20preserveAspectRatio=%22none%22%20width=%22100%22%20height=%2240%22%3E%3Cpath%20d=%22M.8%20.8H99.2L91%2020%2099.2%2039.2H.8L9%2020Z%22%20fill=%22rgba(140,144,242,.32)%22%20stroke=%22%23EDEBF4%22%20stroke-width=%221.3%22%20vector-effect=%22non-scaling-stroke%22/%3E%3C/svg%3E") !important; }
.popup .popup-controls .menu_button.popup-button-cancel {
  background: url("data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%20100%2040%22%20preserveAspectRatio=%22none%22%20width=%22100%22%20height=%2240%22%3E%3Cpath%20d=%22M.8%20.8H99.2L91%2020%2099.2%2039.2H.8L9%2020Z%22%20fill=%22rgba(12,12,16,.5)%22%20stroke=%22rgba(237,235,244,.22)%22%20stroke-width=%221.3%22%20vector-effect=%22non-scaling-stroke%22/%3E%3C/svg%3E") center / 100% 100% no-repeat !important;
  border: 0 !important;
  color: var(--hai-mist) !important;
  padding: 9px 30px !important;
}
.popup .popup-controls .menu_button.popup-button-cancel:hover { color: var(--hai-pearl) !important; }

/* 勾选框：四芒星（不改原生勾的生成链，只把勾画成透明，状态由背景图表达） */
input[type="checkbox"]:not(#nothing) {
  width: 20px !important;
  height: 20px !important;
  min-width: 20px;
  background: url("data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%2020%2020%22%20width=%2220%22%20height=%2220%22%3E%3Cpath%20d=%22M10%201.5C10.8%207.6%2012.4%209.2%2018.5%2010%2012.4%2010.8%2010.8%2012.4%2010%2018.5%209.2%2012.4%207.6%2010.8%201.5%2010%207.6%209.2%209.2%207.6%2010%201.5Z%22%20fill=%22none%22%20stroke=%22%23A9A6C2%22%20stroke-width=%221.2%22%20stroke-linejoin=%22round%22/%3E%3C/svg%3E") center / contain no-repeat !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
input[type="checkbox"]:not(#nothing):checked {
  background-image: url("data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%2020%2020%22%20width=%2220%22%20height=%2220%22%3E%3Cpath%20d=%22M10%201.5C10.8%207.6%2012.4%209.2%2018.5%2010%2012.4%2010.8%2010.8%2012.4%2010%2018.5%209.2%2012.4%207.6%2010.8%201.5%2010%207.6%209.2%209.2%207.6%2010%201.5Z%22%20fill=%22%238C90F2%22%20stroke=%22%238C90F2%22%20stroke-width=%221.2%22%20stroke-linejoin=%22round%22/%3E%3Cpath%20d=%22M10%206C10.4%209%2011%209.6%2014%2010%2011%2010.4%2010.4%2011%2010%2014%209.6%2011%209%2010.4%206%2010%209%209.6%209.6%209%2010%206Z%22%20fill=%22%23fff%22/%3E%3C/svg%3E") !important;
  filter: none !important;
}
input[type="checkbox"]:not(#nothing)::before { box-shadow: inset 1em 1em transparent !important; }
input[type="checkbox"]:not(#nothing):focus-visible { outline: 1px solid var(--hai-peri) !important; outline-offset: 2px; }

/* ───── 滑块：细轨 + 四芒星滑钮 ───── */
input[type="range"] { -webkit-appearance: none; appearance: none; background: transparent !important; height: 22px; }
input[type="range"]::-webkit-slider-runnable-track {
  height: 2px;
  background: linear-gradient(90deg, rgba(var(--hai-peri-rgb), .9), rgba(237, 235, 244, .25)) !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
input[type="range"]::-moz-range-track { height: 2px; background: rgba(237, 235, 244, .25); border: 0; border-radius: 0; }
input[type="range"]::-moz-range-progress { height: 2px; background: var(--hai-peri); }
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 22px !important;
  height: 22px !important;
  margin-top: -10px !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: var(--hai-spark) center / contain no-repeat !important;
  box-shadow: none !important;
  filter: none !important;
  cursor: pointer;
}
input[type="range"]::-moz-range-thumb {
  width: 22px; height: 22px; border: 0; border-radius: 0;
  background: var(--hai-spark) center / contain no-repeat; box-shadow: none;
}

/* ───── 设置面板里的标题块（如“对话补全预设”） ───── */
.standoutHeader {
  background: var(--hai-brk), rgba(20, 19, 30, .85) !important;
  border: 1px solid var(--hai-line) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
.standoutHeader h4, .standoutHeader strong, .standoutHeader b, .standoutHeader span[data-i18n] {
  font-family: var(--hai-font-title);
  font-weight: 400;
  letter-spacing: .12em;
  color: var(--hai-pearl);
}
.range-block-title, #left-nav-panel h4 { font-family: var(--hai-font-body); letter-spacing: .1em; color: var(--hai-pearl); }
.range-block-counter input, .range-block-counter .text_pole,
input[type="number"].text_pole { font-family: var(--hai-font-num); font-style: italic; font-size: 1.05em; letter-spacing: .04em; }
.toggle-description, .range-block small, .notes-link, .text_muted, small { color: var(--hai-mist); opacity: 1 !important; }

/* ───── 预设提示词列表（Prompt Manager） ───── */
/* 大块用流光：整张列表外框在转；每一行保持安静 */
#completion_prompt_manager_list {
  background: rgba(12, 12, 16, .45) !important;
  border: 1.5px solid transparent !important;
  border-image: conic-gradient(from var(--hai-ang), rgba(255,255,255,.95), rgba(140,144,242,.6) 14%, rgba(237,235,244,.06) 33%, rgba(142,230,242,.55) 48%, rgba(255,255,255,.9) 56%, rgba(140,144,242,.18) 74%, rgba(255,154,203,.55) 87%, rgba(255,255,255,.95)) 1 !important;
  border-radius: 0 !important;
  padding: 6px 8px !important;
  animation: hai-spin 12s linear infinite;
}
#completion_prompt_manager_list li.completion_prompt_manager_list_head {
  font-family: var(--hai-font-num);
  font-style: italic;
  color: var(--hai-mist);
  letter-spacing: .1em;
}
#completion_prompt_manager_list li.completion_prompt_manager_prompt {
  background: rgba(20, 19, 30, .6) !important;
  border: 1px solid rgba(237, 235, 244, .1) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  margin: 4px 0 !important;
  color: var(--hai-pearl) !important;
  opacity: 1 !important;
  filter: none !important;
}
#completion_prompt_manager_list li.completion_prompt_manager_prompt:hover { border-color: rgba(var(--hai-peri-rgb), .45) !important; }
#completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
  background: transparent !important;
  border: 1px dashed rgba(237, 235, 244, .12) !important;
}
#completion_prompt_manager_list .completion_prompt_manager_prompt_name,
#completion_prompt_manager_list .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
  font-family: var(--hai-font-body);
  letter-spacing: .06em;
  color: var(--hai-pearl) !important;
  opacity: 1 !important;
}
#completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
  color: var(--hai-mist) !important;
  text-decoration: line-through rgba(var(--hai-peri-rgb), .55);
}
#completion_prompt_manager_list .completion_prompt_manager_prompt_name > .fa-solid,
#completion_prompt_manager_list .drag-handle { color: rgba(var(--hai-peri-rgb), .9) !important; opacity: 1 !important; filter: none !important; }
#completion_prompt_manager_list .prompt_manager_prompt_controls span,
#completion_prompt_manager_list .prompt_manager_prompt_controls .caution {
  color: var(--hai-mist) !important;
  opacity: 1 !important;
  filter: none !important;
  text-shadow: none !important;
}
#completion_prompt_manager_list .prompt_manager_prompt_controls span:hover { color: var(--hai-pearl) !important; }
#completion_prompt_manager_list .prompt_manager_prompt_controls .caution:hover { color: #FF9ACB !important; }
/* 开关：大一点的滑动开关，低亮度 */
#completion_prompt_manager_list .prompt-manager-toggle-action::before { content: "" !important; }
#completion_prompt_manager_list .prompt_manager_prompt_controls .prompt-manager-toggle-action {
  display: inline-block;
  font-size: 0 !important;
  width: 40px !important;
  height: 20px !important;
  background: url("data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%2040%2020%22%20width=%2240%22%20height=%2220%22%3E%3Cpath%20d=%22M10%203L17%2010%2010%2017%203%2010Z%22%20fill=%22%236E6A88%22/%3E%3Cpath%20d=%22M30%203L37%2010%2030%2017%2023%2010Z%22%20fill=%22none%22%20stroke=%22rgba(237,235,244,.3)%22%20stroke-width=%221.2%22/%3E%3Cpath%20d=%22M17%2010H23%22%20stroke=%22rgba(237,235,244,.25)%22%20stroke-width=%221%22/%3E%3C/svg%3E") center / contain no-repeat !important;
  color: transparent !important;
  vertical-align: middle;
}
#completion_prompt_manager_list .prompt_manager_prompt_controls .prompt-manager-toggle-action.fa-toggle-on { background-image: url("data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%2040%2020%22%20width=%2240%22%20height=%2220%22%3E%3Cpath%20d=%22M10%203L17%2010%2010%2017%203%2010Z%22%20fill=%22none%22%20stroke=%22rgba(140,144,242,.5)%22%20stroke-width=%221.2%22/%3E%3Cpath%20d=%22M30%203L37%2010%2030%2017%2023%2010Z%22%20fill=%22%238C90F2%22/%3E%3Cpath%20d=%22M30%206.5L30.7%209.3%2033.5%2010%2030.7%2010.7%2030%2013.5%2029.3%2010.7%2026.5%2010%2029.3%209.3Z%22%20fill=%22%23fff%22/%3E%3Cpath%20d=%22M17%2010H23%22%20stroke=%22%238C90F2%22%20stroke-width=%221%22/%3E%3C/svg%3E") !important; }
#completion_prompt_manager_list .prompt_manager_prompt_tokens {
  font-family: var(--hai-font-num);
  font-style: italic;
  font-size: 1.05em;
  color: var(--hai-pearl) !important;
}
#completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .prompt_manager_prompt_tokens { color: var(--hai-mist) !important; }
#completion_prompt_manager_footer .menu_button, #completion_prompt_manager_popup .menu_button { min-height: 0; }

/* 浅色框里的字要看得清 */
.popup input.text_pole, .popup textarea.text_pole { color: var(--hai-pearl) !important; }
.text_pole::placeholder, textarea::placeholder, input::placeholder { color: var(--hai-mist) !important; opacity: 1 !important; }

/* ───── 通用控件（续） ───── */
.text_pole, select, textarea.text_pole {
  background: var(--hai-field) !important;
  border: 1px solid var(--hai-line) !important;
  border-radius: 0 !important;
  color: var(--hai-pearl) !important;
  font-family: var(--hai-font-body);
}
.text_pole:focus, select:focus, textarea:focus {
  border-color: var(--hai-peri) !important;
  box-shadow: 0 0 0 1px rgba(var(--hai-peri-rgb), .55) !important;
  outline: none;
}
.text_pole::placeholder { color: var(--hai-mist); opacity: 1; }
option { background: var(--hai-panel-solid); color: var(--hai-pearl); }
:focus-visible { outline: 1px solid var(--hai-peri) !important; outline-offset: 2px; }

.select2-container .select2-selection {
  background: var(--hai-field) !important;
  border: 1px solid var(--hai-line) !important;
  border-radius: 0 !important;
  color: var(--hai-pearl) !important;
}
.select2-dropdown { background: var(--hai-panel-solid) !important; border: 1px solid var(--hai-line-strong) !important; border-radius: 0 !important; }
.select2-results__option { color: var(--hai-pearl) !important; }
.select2-results__option--highlighted { background: rgba(var(--hai-peri-rgb), .25) !important; }
.select2-selection__choice, .tag {
  background: rgba(var(--hai-peri-rgb), .14) !important;
  border: 1px solid rgba(var(--hai-peri-rgb), .5) !important;
  border-radius: 0 !important;
  color: var(--hai-pearl) !important;
  filter: none !important;
}

/* 菜单 / 列表 / 角色列表 */
#extensionsMenu, #options .options-content, .list-group, #quickReplyPopoutMenu {
  background: var(--hai-brk), var(--hai-panel-solid) !important;
  border: 1px solid var(--hai-line-strong) !important;
  border-radius: 0 !important;
  box-shadow: 0 12px 40px rgba(0, 0, 0, .5) !important;
}
#extensionsMenu .list-group-item, #options .options-content a, .list-group-item {
  color: var(--hai-pearl) !important;
  opacity: 1 !important;
  font-family: var(--hai-font-body);
  letter-spacing: .06em;
}
#extensionsMenu .list-group-item:hover, #options .options-content a:hover, .list-group-item:hover {
  background: rgba(var(--hai-peri-rgb), .16) !important;
}
#rm_print_characters_block .character_select,
#rm_print_characters_block .group_select,
#rm_print_characters_block .bogus_folder_select { border-radius: 0 !important; }
#rm_print_characters_block .character_select:hover,
#rm_print_characters_block .group_select:hover { background: rgba(var(--hai-peri-rgb), .1) !important; }
#rm_print_characters_block .ch_name { font-family: var(--hai-font-body); color: var(--hai-pearl) !important; letter-spacing: .06em; }
#rm_print_characters_block .avatar, #rm_print_characters_block .avatar img { border-radius: 0 !important; }

/* 通知 */
#toast-container > .toast {
  background-color: var(--hai-panel-solid) !important;
  border: 1px solid var(--hai-line-strong) !important;
  border-radius: 0 !important;
  box-shadow: 0 12px 40px rgba(0, 0, 0, .5) !important;
  color: var(--hai-pearl) !important;
  opacity: .97 !important;
  font-family: var(--hai-font-body);
}

/* ───── 手机 ───── */
@media (max-width: 1000px) {
  :root { --hai-scene-size: 100vw; --hai-scene-top: calc(var(--topBarBlockSize, 50px) + 1vh); }
  #chat .mes { margin: 56px 6px 22px !important; padding: 0 14px 20px !important; }
  #chat .mes .ch_name .name_text { font-size: 1.6em; }
}
@media (prefers-reduced-motion: reduce) {
  body::before { background-image: var(--hai-grain), none, var(--hai-scene), linear-gradient(180deg, rgba(12, 12, 16, var(--hai-floor-alpha)) 58%, rgba(35, 29, 85, var(--hai-floor-alpha))); }
}

#chat .mes[is_user="true"] > .mes_block::after { background: var(--hai-hr-inf-ink) center / 56px 20px no-repeat, #E7E1EE; }
